INSERT INTO answers(id, question_id, text, correct) VALUES
('e22bc6cc-3ab1-4e7c-b426-c6bc1a2ff334','2a60add0-4d2e-48f9-bf49-bf4d2f892dae','Los proyectos de ley serán aprobados en Consejo de Ministros, que los someterá al Congreso, acompañados de una exposición de motivos y de los antecedentes necesarios para pronunciarse sobre ellos.',false),
('67dcb24a-6a90-4540-8145-08c9ad86419d','2a60add0-4d2e-48f9-bf49-bf4d2f892dae','Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar.',true),
('dea05ef0-ca7b-4a2c-9b23-9ba0eb038959','2a60add0-4d2e-48f9-bf49-bf4d2f892dae','Los Estatutos podrán prever los supuestos, requisitos y términos en que las Comunidades Autónomas podrán celebrar convenios entre sí para la gestión y prestación de servicios propios de las mismas, así como el carácter y efectos de la correspondiente comunicación…',false),
('4770fef7-606e-42ab-8dd3-a59b5b0d2c9b','2a60add0-4d2e-48f9-bf49-bf4d2f892dae','La utilización injustificada o abusiva de las facultades reconocidas en dicha ley orgánica producirá responsabilidad penal, como violación de los derechos y libertades reconocidos por las leyes.',false),
('6ffdb201-2063-41f7-94b9-eb4f06c5bd3a','bb198ece-752c-4f33-a04d-1e8e343e5253','Sección 2.ª De los derechos y deberes de los ciudadanos',false),
('abb85b9c-dcdc-46ed-aa2e-1ece4cb89316','bb198ece-752c-4f33-a04d-1e8e343e5253','La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados.',false),
('70e8f3f7-51f8-4f6c-b106-094c7b6e0d89','bb198ece-752c-4f33-a04d-1e8e343e5253','Los Estatutos de autonomía deberán contener: a) La denominación de la Comunidad que mejor corresponda a su identidad histórica.',false),
('437924df-7cac-4352-9f24-4afaabb2a3a9','bb198ece-752c-4f33-a04d-1e8e343e5253','b) A la producción y creación literaria, artística, científica y técnica.',true),
('5b352c8a-05a8-493c-82b5-71aacaecff65','288c6b95-fc0d-4979-b0a4-9965540a30ec','Los padres deben prestar asistencia de todo orden a los hijos habidos dentro o fuera del matrimonio, durante su minoría de edad y en los demás casos en que legalmente proceda.',false),
('a583b6d5-9042-4b24-a75f-8ccc60e5546b','288c6b95-fc0d-4979-b0a4-9965540a30ec','Los poderes públicos garantizan el derecho que asiste a los padres para que sus hijos reciban la formación religiosa y moral que esté de acuerdo con sus propias convicciones.',true),
('4f9918bb-90b2-4650-b5c6-2e1f83d19229','288c6b95-fc0d-4979-b0a4-9965540a30ec','Corresponde a los poderes públicos promover las condiciones para que la libertad y la igualdad del individuo y de los grupos en que se integra sean reales y efectivas; remover los obstáculos que impidan o dificulten su plenitud y facilitar…',false),
('e55ffe29-f0cf-485a-bb38-1aa0616a96e2','288c6b95-fc0d-4979-b0a4-9965540a30ec','Las Cámaras y sus Comisiones podrán recabar, a través de los Presidentes de aquéllas, la información y ayuda que precisen del Gobierno y de sus Departamentos y de cualesquiera autorida des del Estado y de las Comunidades Autónomas.',false),
('e5a7211c-861c-4f50-a00a-cd362a384668','251b21c4-950d-4595-9b0e-3c784e662201','Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.',true),
('88f8cc1c-0a87-4c58-9ac6-1fd5009c66c4','251b21c4-950d-4595-9b0e-3c784e662201','Las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada.',false),
('2ae1c50c-a2cf-49c1-af01-dca383476746','251b21c4-950d-4595-9b0e-3c784e662201','El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.',false),
('23b94a31-dae7-43ed-8ca8-2fdba6986f85','251b21c4-950d-4595-9b0e-3c784e662201','b) A los altos cargos de la Administración del Estado que determine la ley, con la excepción de los miembros del Gobierno.',false),
('d8815e05-fe77-46bf-8ea0-1739d9794af9','51b2b392-26c7-437a-92e8-a62e08d04bac','Una ley orgánica podrá determinar la forma y los casos en los que, de forma individual y con la necesaria intervención judicial y el adecuado control parlamentario, los derechos reconocidos en los artículos 17, apartado 2, y 18, apartados 2…',true),
('3f9efe32-24d2-462c-a89a-d194b0358d87','51b2b392-26c7-437a-92e8-a62e08d04bac','Los recursos de las Comunidades Autónomas estarán constituidos por: a) Impuestos cedidos total o parcialmente por el Estado; recargos sobre impuestos estatales y otras participaciones en los ingresos del Estado.',false),
('a71e389d-4078-4ef1-93f0-445322555dda','51b2b392-26c7-437a-92e8-a62e08d04bac','El Estado y las Comunidades Autónomas no podrán incurrir en un déficit estructural que supere los márgenes estable cidos, en su caso, por la Unión Europea para sus Estados Miembros.',false),
('2a68f155-78c6-45e2-ad37-ba96062198d7','51b2b392-26c7-437a-92e8-a62e08d04bac','º El Gobierno convocará a todos los Diputados y Sena dores elegidos en las circunscripciones comprendidas en el ámbito territorial que pretenda acceder al auto gobierno, para que se constituyan en Asamblea, a los solos efectos de elaborar el correspondiente…',false),
('d608cddb-dbe0-47a4-a4ab-3cf9dbecf080','422a7916-65cc-41b9-8a7a-691ecbafdc2f','Los poderes públicos promoverán la ciencia y la investiga ción científica y técnica en beneficio del interés general.',false),
('347d07bd-c552-4a73-946f-ceceeb8e9bed','422a7916-65cc-41b9-8a7a-691ecbafdc2f','Don Juan Carlos I de Borbón, legítimo heredero de la dinastía histórica.',true),
('892d3fee-a575-4802-802b-30b1948ee3fc','422a7916-65cc-41b9-8a7a-691ecbafdc2f','La prerrogativa real de gracia no será aplicable a ninguno de los supuestos del presente artículo.',false),
('e91864ee-b0f1-407b-91f6-08fb591a26c1','422a7916-65cc-41b9-8a7a-691ecbafdc2f','La comunidad participará en las plusvalías que genere la acción urbanística de los entes públicos.',false),
('3d248670-0fee-47ea-8383-7d346a06c2c1','5947c2cd-7be3-4117-a366-0b2b16b0262e','Sus conclusiones no serán vinculantes para los Tribunales, ni afectarán a las resoluciones judiciales, sin perjuicio de que el resultado de la investigación sea comunicado al Ministerio Fiscal para el ejercicio, cuando proceda, de las acciones oportunas.',false),
('a9d5caa4-0634-451c-8d98-ed86c3f0f1bf','5947c2cd-7be3-4117-a366-0b2b16b0262e','El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá…',false),
('b4d980f4-7ec3-470c-bfc4-1e54313bb60f','5947c2cd-7be3-4117-a366-0b2b16b0262e','Cuando el Rey fuere menor de edad, el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona, según el orden establecido en la Constitución, entrará a ejercer…',true),
('6b024889-00e6-47dc-b936-807a3193eab7','5947c2cd-7be3-4117-a366-0b2b16b0262e','El control de la actividad de los órganos de las Comunidades Autónomas se ejercerá: a) Por el Tribunal Constitucional, el relativo a la constitucionalidad de sus disposiciones normativas con fuerza de ley.',false),
('0f891d21-6e3f-4981-b651-a7dd4682afde','1d3806dd-c696-484b-ba2a-0ec5d32a704b','La prerrogativa real de gracia no será aplicable a ninguno de los supuestos del presente artículo.',false),
('a645c220-b6e7-4b8d-a0dc-ce8d8484702c','1d3806dd-c696-484b-ba2a-0ec5d32a704b','c) Transferencias de un Fondo de Compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado.',false),
('9490d593-38ce-4df7-840e-c30aaf77bcd3','1d3806dd-c696-484b-ba2a-0ec5d32a704b','b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución.',true),
('5f0a91fb-7f25-4521-b0a3-d5be2a99f881','1d3806dd-c696-484b-ba2a-0ec5d32a704b','Quedan excluidos de la extradición los delitos políticos, no considerándose como tales los actos de terrorismo.',false),
('19102608-307f-402f-a288-c47d71500618','9b8cc66a-53e8-4ddb-859f-dc935c08c497','Los Diputados y Senadores percibirán una asignación que será fijada por las respectivas Cámaras.',false),
('04d8ab15-233c-4d29-ae68-64dd4f1f2d02','9b8cc66a-53e8-4ddb-859f-dc935c08c497','Las poblaciones de Ceuta y Melilla estarán representadas cada una de ellas por un Diputado.',true),
('5d246550-ef9f-4a54-a548-e3bced8ae133','9b8cc66a-53e8-4ddb-859f-dc935c08c497','No podrán ser inculpados ni procesados sin la previa autorización de la Cámara res pectiva.',false),
('f75bd29c-8374-4703-910c-59783120ffd4','9b8cc66a-53e8-4ddb-859f-dc935c08c497','La celebración de un tratado internacional que contenga estipulaciones contrarias a la Constitución exigirá la previa revisión constitucional.',false),
('a0afe287-644b-48d2-a58d-300b0b1ae5d5','95ca7953-cef5-45bc-bfb7-65cce42d9d3f','Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.',true),
('f1b7a710-ecda-4354-b4d0-0b0e0e60d6b5','95ca7953-cef5-45bc-bfb7-65cce42d9d3f','Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere.',false),
('9524dd14-ef73-40b9-ae2b-dd066aadb3a7','95ca7953-cef5-45bc-bfb7-65cce42d9d3f','Se atenderán particularmente las necesidades específicas de las mujeres y los menores con discapacidad.',false),
('132af28a-5043-4939-9cbb-dcea171708ed','95ca7953-cef5-45bc-bfb7-65cce42d9d3f','La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.',false),
('7a170a8f-bfcf-45af-9e12-cc3a3a01df89','259ee8e6-9be4-4632-b91e-d8538b2c5750','f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes.',false),
('bb1d39fb-ddac-426c-8c4b-190a13d65733','259ee8e6-9be4-4632-b91e-d8538b2c5750','La comunidad participará en las plusvalías que genere la acción urbanística de los entes públicos.',false),
('ced16cd1-d471-4949-90e2-ee007ad86ab3','259ee8e6-9be4-4632-b91e-d8538b2c5750','La delegación legislativa habrá de otorgarse al Gobierno de forma expresa para materia concreta y con fijación del plazo para su ejercicio.',true),
('4dc03e02-426b-42df-af60-cc38e28cc08b','259ee8e6-9be4-4632-b91e-d8538b2c5750','En cada provincia se elegirán cuatro Senadores por sufragio universal, libre, igual, directo y secreto por los votantes de cada una de ellas, en los términos que señale una ley orgánica.',false),
('7816b40f-fa4f-4ee3-b593-ea0fce6d57c2','ab83069e-8f34-43a3-b5fe-e9c10dd36824','El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo.',true),
('2c82268b-d473-4f24-92d0-bb7fedc9ca5a','ab83069e-8f34-43a3-b5fe-e9c10dd36824','El Estado, mediante ley, podrá planificar la actividad económica general para atender a las necesidades colectivas, equilibrar y armonizar el desarrollo regional y sectorial y estimular el crecimiento de la renta y de la riqueza y su más justa distribución.',false),
('e6b28bb5-ffe5-459a-afc2-fcf10c9ca961','ab83069e-8f34-43a3-b5fe-e9c10dd36824','La delegación legislativa deberá otorgarse mediante una ley de bases cuando su objeto sea la formación de textos arti culados o por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo.',false),
('1cf86d7b-0574-47eb-9b90-491ae564622b','ab83069e-8f34-43a3-b5fe-e9c10dd36824','El condenado a pena de prisión que estuviere cumpliendo la misma gozará de los derechos fundamentales de este Capítulo, a excep ción de los que se vean expresamente limitados por el contenido del fallo condenatorio, el sentido de la pena…',false),
('1df7bc85-b71a-4ac6-9909-81974204b4dc','0b39a9e5-f12c-42a4-bdab-5284aed508fe','El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corres ponde exclusivamente a los Juzgados y Tribunales determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan.',false),
('8099dce8-4add-4281-8b98-7bd9302483b3','0b39a9e5-f12c-42a4-bdab-5284aed508fe','La ley que regule el ejercicio de este derecho, sin perjuicio de las limitaciones que puedan establecer, incluirá las garantías precisas para asegurar el funcionamiento de los servicios esenciales de la comunidad.',false),
('cf3688fb-9fdd-4dbd-8930-ca90352ff860','0b39a9e5-f12c-42a4-bdab-5284aed508fe','Las Comunidades Autónomas podrán actuar como delegados o colaboradores del Estado para la recaudación, la gestión y la liquidación de los recursos tributarios de aquél, de acuerdo con las leyes y los Estatutos.',false),
('b9736396-94e3-448e-a2c8-a125c26976e0','0b39a9e5-f12c-42a4-bdab-5284aed508fe','Después de cada renovación del Congreso de los Diputa dos, y en los demás supuestos constitucionales en que así proceda, el Rey, previa consulta con los representantes designados por los Grupos políticos con representación parlamentaria, y a través del Presidente…',true),
('3b0cc8b3-3b5f-49f2-9270-6df8c2e4df66','09ab4580-135f-4112-8f2f-1385dbf43dc8','El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros del mismo, sin perjuicio de la competencia y responsabilidad directa de éstos en su gestión.',false),
('e15dd332-485b-4b2d-a2df-2d01d53a95c7','09ab4580-135f-4112-8f2f-1385dbf43dc8','El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá…',true),
('80494fe8-e582-4393-b0bd-4709c16ecdcf','09ab4580-135f-4112-8f2f-1385dbf43dc8','juan caRlos el pResidente de las coRtes ANTONIO HERNÁNDEZ GIL el pResidente del congReso de los diputados FERNANDO ÁLVAREZ DE MIRANDA Y TORRES el pResidente del senado antonio fontán pÉReZ',false),
('06fcd47e-17ea-443c-a56f-00cba31ab0e0','09ab4580-135f-4112-8f2f-1385dbf43dc8','En las provincias insulares, cada isla o agrupación de ellas, con Cabildo o Consejo Insular, constituirá una circunscripción a efectos de elección de Senadores, correspondiendo tres a cada una de las islas mayores –Gran Canaria, Mallorca y Tenerife– y uno…',false),
('dde0201d-74c9-4edc-bce7-17d2b73566e2','0bebe7e3-a6cf-4fa7-a51d-a921defee2e9','Todo ello de conformidad con lo previsto en la ley orgánica del poder judicial y dentro de la unidad e independencia de éste.',false),
('13f8e0f7-ea8f-4606-845f-f082fdc38178','0bebe7e3-a6cf-4fa7-a51d-a921defee2e9','La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.',true),
('0f7b4aa3-b0d1-4baa-a8fb-d86834420ea7','0bebe7e3-a6cf-4fa7-a51d-a921defee2e9','La ley que regule el ejercicio de este derecho establecerá las garantías precisas para asegurar el mantenimiento de los servicios esenciales de la comunidad.',false),
